pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let post = post_residual ;
    let cap = bin_capacity as f64 ;
    let quarter = bin_capacity / 4 ;
    let fifth = bin_capacity / 5 ;
    let tenth = bin_capacity / 10 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if post_residual < tenth {
            score += 35.0 ;
        } else if post_residual < fifth {
            score += 20.0 ;
        } else if post_residual < quarter {
            score += (40.0 - post_residual as f64) * 0.5 ;
        } else {
            score -= 5.0 ;
        }
        let pr = post_residual ;
        let clean = pr % 20 == 0 || pr % 25 == 0 || pr % 10 == 0 ;
        if clean { score -= 16.0 ; }
        else if pr % 5 == 0 { score -= 5.0 ; }
        if pr >= 10 && pr % 25 <= 10 { score -= 5.0 ; }
        if pr <= 3 { score -= 45.0 ; }
        else if pr <= 6 { score -= 26.0 ; }
        if pr < 12 && pr % 5 != 0 { score += 32.0 ; }
        else if pr < 20 && pr % 5 != 0 { score += 12.0 ; }
        // awkward fragment penalty: residuals unlikely to match future item sizes
        if pr > 0 && pr < 15 && pr % 3 != 0 && pr % 5 != 0 && pr % 7 != 0 {
            score += 9.0 ;
        }
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 106.0 ;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_post = post_residual - next_item_size ;
            let chain_bonus = if chain_post == 0 { 30.0 }
                else if chain_post <= 4 { 18.0 }
                else if chain_post <= 10 { 7.0 }
                else { 0.0 } ;
            score -= 30.0 * (1.0 - slack / cap) . max (0.0) + chain_bonus ;
            if chain_post >= 1 && chain_post <= 12 && (chain_post as f64) <= mean_residual {
                score -= 6.0 ;
            }
        } else {
            let over = (next_item_size - post_residual) as f64 ;
            score += 8.0 + over * (if over > 28.0 { 0.16 } else { 0.55 }) ;
            if post > 0 && (post as f64 - mean_residual) . abs () < 2.0 {
                score -= 4.0 ;
            }
        }
    }

    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 2.0 * tightness * post_residual as f64 / cap ;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 ;
    }

    if bin_residual == bin_capacity {
        score += 30.0 ;
        score -= 20.0 * (1.0 - progress) ;
        if mean_residual < cap * 0.25 { score -= 17.0 ; }
        if next_item_size > 0 && next_item_size as f64 > mean_residual { score -= 12.0 ; }
        if next_item_size > 0 && bin_residual >= item_size {
            let dead = (bin_capacity - item_size) as f64 ;
            if dead > 45.0 { score -= 10.0 ; }
        }
        let item = item_size as f64 ;
        if item > 0.55 * cap && fitting_bins_count <= 1 {
            score -= 20.0 * (item / cap - 0.55) ;
        }
        if progress > 0.85 { score += 8.0 ; }
        score += 14.0 * (item / cap) ;
    } else {
        if post > 0 && next_item_size > 0 && post < next_item_size {
            score += 0.04 * post as f64 * (1.0 + progress) ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 && post_residual < next_item_size {
            score += 6.0 ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64) . min (6.0) ;
        }
        if open_bins_count > 6 && post > 0 && post < 25 {
            score += 3.0 ;
        }
    }

    score -= (bin_residual as f64 / cap) * 5.0 ;
    let pr = post_residual as f64 ;
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress) ;
        } else {
            score -= 0.5 * (pr - nx) . min (20.0) / cap ;
        }
    }
    score
}

