pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 40.0 * tightness;

    // Last-chance bin: strong reward to use it, else a new bin opens
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // penalize dead space that cannot host the next item
            score += 10.0 + (post_residual as f64 / bin_capacity as f64) * 20.0;
        }
    }

    // Penalize leaving residuals in the awkward zone (just below smallest items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins below the mean residual (fill the emptier bins less)
    if open_bins_count > 1 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 20.0 * diff;
    }

    // Time horizon: early in the stream, be pickier about tight fits;
    // late in the stream, just minimize bins opened
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: mild penalty so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified by stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress) + norm_pr * norm_pr * 30.0 * (0.5 + progress);

    // Reward tight fits (low post_residual) increasingly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0 * (0.3 + 0.7 * progress);

    // Smoothly penalize opening new bins, more aggressively later in the stream
    let new_bin_penalty = 6.0 + 14.0 * progress * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 2.0 + 4.0 * progress;
    }

    // Last-chance bin: strong smooth reward for using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Coupling with lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Mild coupling to mean residual: prefer bins deviating below mean (consolidating waste)
    score += 0.05 * (mean_residual - pr) * (0.5 + progress);

    // Mild preference for bins in a moderately-sized open set
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers in the "dead zone" (tiny fragments
    // that almost nothing can use) are heavily penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity remaining

    // Integer-division thresholds on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;   // 25
    let eighth = bin_capacity / 8;    // 12
    let half = bin_capacity / 2;      // 50

    if post_residual == 0 {
        // Perfect packing: strongly reward.
        score -= 60.0;
    } else if post_residual < eighth {
        // Dead space: fragment too small for the smallest plausible item.
        score += 45.0;
    } else if post_residual < quarter {
        // Small-but-usable leftover: mild penalty, modulated by how many
        // other bins could also take this item (competition reduces risk).
        score += 8.0 - (fitting_bins_count as f64).min(5.0);
    } else if post_residual <= half {
        // Sweet spot: leftover in the lower-middle band, still very fillable.
        score -= 12.0;
    } else {
        // Large leftover: bin remains flexible, small bonus.
        score -= 4.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common item-size classes (multiples of 10, and multiples of 5) pair
    // well with typical streams; reward exact divisibility classes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        // Odd fragment: slight penalty proportional to how far from a
        // multiple of 5 it lands.
        let off5 = (post_residual % 5) as f64;
        score += off5 * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up; reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight follow-up fits, penalize setups leaving dead space.
            if slack < eighth as f64 {
                score += 20.0;
            } else {
                score -= slack / 8.0;
            }
        } else {
            // Next item cannot use the leftover: leftover likely wasted
            // unless another bin handles it; small penalty.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin only attractive when the
    // item is large relative to a typical open residual or open bins are
    // badly fragmented. Base new-bin score should be near post_residual
    // (= capacity - item_size) with a mild exploration penalty.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; they win only when all open bins score
        // poorly (heavy dead-space penalties above).
        score += 10.0
            + 0.15 * mean_residual
            - (frac * 20.0);
        // If the item is huge, a fresh bin is often the right home.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Stream progression: later in the stream, consolidate harder —
    // penalize leaving any leftover as the end approaches.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post / 10.0);

    // Mean-residual coupling: when open bins are already loose on average,
    // favor the tightest fit more aggressively (waste-averse regime).
    if mean_residual > half as f64 {
        score += (frac - 0.25).max(0.0) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items are >= 1, but gaps below a usable threshold ~ 10 in classic regime)
    // are pure waste. Penalize gaps in the "dead zone" (0 < post_residual < 10)
    // heavily, scaled by how much of the bin was consumed.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: post_residual small relative to item size
    if item_size > 0 {
        score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin becomes more costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream
        // is late; slight discount early when open_bins_count is small.
        score += 15.0 + 2.5 * open_bins_count as f64 + 10.0 * progress;
        // If next item is large and no open bin would fit it, opening a fresh
        // bin now can be wise: soften penalty.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: mild bonus for choosing bins below mean residual
        // (keeps residual distribution balanced, avoids many half-full bins).
        score -= 3.0 * ((mean_residual - bin_residual as f64) / bin_capacity as f64);
        // If the next item fits exactly in the post-residual, reward keeping
        // this bin for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best; add convex penalty for waste.
    let pr = post_residual as f64;
    score += 0.6 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space (< 10, unusable for min item) more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into the resulting post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Early in the stream, be more willing to open new bins (exploration);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 20.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // But if item is large relative to capacity, new bin is reasonable.
        score -= 0.25 * item_size as f64;
    } else if progress < 0.2 {
        score -= 5.0; // mild exploration discount early
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * (pr / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "slot classes".
    let post_class = post_residual % 10;
    // Small post_residuals are excellent: near-perfect packing.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual >= 90 {
        score += 40.0; // nearly-empty bin wasted on a small item
    }

    // Dead-space penalty: residuals in (10, 20) are risky since min item is 1..=100
    // but typical small items ~10; unusable slivers get punished via class coupling.
    if post_residual > 10 && post_residual < 20 {
        score += 15.0 + (post_residual as f64 - 10.0);
    }

    // Integer-division threshold: does post_residual still fit a "harmonic divisor"
    // of the capacity (50, 25, 20, 10)? Reward bins that remain useful.
    let useful = (post_residual >= 50) as f64 * 12.0
        + ((25..50).contains(&post_residual)) as i32 as f64 * 6.0
        + ((10..25).contains(&post_residual)) as i32 as f64 * 2.0;
    score -= useful;

    // Modulo coupling with next_item_size: if the lookahead item fits exactly
    // into post_residual, big reward (chain fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 45.0;
        } else if gap <= 5.0 {
            score -= 18.0;
        } else if gap <= 10.0 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    }
    // If the next item cannot fit here and will force a new bin anyway,
    // slightly prefer using this bin now (soften score).
    if next_item_size > post_residual && post_residual < next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening new bins.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when current residuals
    // are all tight (mean residual low) and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin, discounted if item is huge or mean residual tiny.
        let mut open_cost = 55.0 - 30.0 * item_frac;
        if mean_residual < 15.0 {
            open_cost -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_frac > 0.5 {
            open_cost -= 10.0;
        }
        open_cost += 10.0 * progress; // later in stream, reusing bins matters more
        score += open_cost;
    }

    // Mild pressure toward bins below mean residual (balance exploitation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0; // moderately awkward gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // dead space for the known next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, avoid spreading; with few, consolidation is fine.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // New-bin candidate: only attractive when it beats poor fits into open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
    }

    // Slight preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits: penalize leftover slack after both placements.
            let second_residual = post_residual - next_item_size;
            score += second_residual as f64 * 0.3;
        } else {
            // Next item won't fit here: prefer leaving a reusable residual
            // close to typical small sizes; penalize dead space.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += (10.0 - dead) * 2.0; // tiny unusable sliver
            }
        }
    }

    // Compare residual against mean residual of open bins: keeping balance
    // avoids fragmenting; bins far below mean residual are precious.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, be more willing to open new bins (cheap future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score += 10.0 + 40.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pair fits nicely in a fresh bin
        }
    }

    // Many open bins: discourage spreading; prefer consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual already favored).

    // Lookahead: reward if the next item also fits in the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.08 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that wastes future capacity slightly.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin for an item that fits here.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: it should only win when no open bin offers a decent fit.
    // Give it a penalty so it only beats open bins with very large post_residual.
    if bin_residual == bin_capacity {
        score += 12.0
            + 0.10 * open_bins_count as f64
            + 0.02 * (mean_residual.max(0.0));
    } else {
        // Reward using existing bins more when many bins are already open.
        score -= 0.05 * open_bins_count as f64;
    }

    // Prefer filling bins whose residual is close to the item (relative tightness).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 4.0 * tightness;
    }

    // Time horizon: early in the stream, be slightly more conservative (favor tight fits
    // to preserve flexibility); late in the stream, just close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating tiny dead space that almost nothing can use (1..=5 residual),
    // but only when the next item can't use it.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0;
    }

    // Mild coupling with mean residual: if open bins are already loose on average,
    // avoid making this bin even looser.
    if (post_residual as f64) > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: as stream advances, demand tighter fits more strongly
    let tightness = 0.5 + 2.0 * progress * progress;
    score += tightness * pr * (1.0 - norm_item);

    // Reward near-perfect fills with smooth quadratic bonus
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Dead-space penalty: small residuals that can't fit typical items
    let dead = if norm_pr < 0.1 { (0.1 - norm_pr) * (0.1 - norm_pr) } else { 0.0 };
    score += 400.0 * dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item would fit poorly here afterward
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).abs();
        score += 0.15 * gap * (1.0 - progress);
        // reward leaving space exactly usable by next item
        score -= 8.0 * (1.0 - (norm_next / (norm_pr + 1e-9)).abs().min(1.0)) * norm_next * (1.0 - norm_pr);
