pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are very costly.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable tiny gap
    }
    // A gap that cannot fit the lookahead item is risky if it is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Reward good proportional fill.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (penalize opening new bins), but with few open bins allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 25.0 + (open_bins_count as f64) * 6.0 + 30.0 * progress;
    } else {
        // Existing bin gets a mild discount, stronger with more open bins.
        score -= (open_bins_count as f64).sqrt() * 8.0;
    }

    // Prefer bins with below-mean residual (tighter bins) to preserve large gaps elsewhere.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place item so next item fits exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits with small slack: mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack * 0.8;
    }
    // Next item does NOT fit the leftover: penalize dead space, worse when tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        if post_residual == 0 {
            score -= 60.0; // perfect fill now, next item goes elsewhere
        } else if post_residual < 10 {
            score += 40.0; // nearly unusable sliver
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Reward bins with residual below the mean (tight packing), penalize hoarding space.
    score += (mean_residual - post_residual as f64) * -0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it unattractive unless residuals elsewhere are hopeless.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
    }

    // Late in stream: prefer closing bins tightly (fill rather than spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a superlinear term.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward near-exact fills: if post_residual is tiny, big bonus.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that no future item (sizes 1..=100) can use well.
    if post_residual > 50 {
        score += 8.0; // large leftover is usually fine actually (next big item fits)
    } else if post_residual >= 1 && post_residual < 10 {
        score += 6.0 * (1.0 - post_residual as f64 / 10.0); // awkward sliver
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after this placement: mild penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // base reluctance to open new bins
        score += 15.0 + open_bins_count as f64;
        // but if current bin fit is very poor, opening fresh is attractive
        if post_residual > 0 && (post_residual as f64) < item_size as f64 * 0.25 {
            score -= 10.0;
        }
        // early in stream, more willingness to open bins (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (avoid fragmenting).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post as f64 * 0.95 + ((bin_capacity / 10) as f64) * 0.05 ;
    if post == 0 {
        score -= 82.0 ;
    } else if post <= 3 {
        score -= 42.0 ;
    } else if post <= 6 {
        score -= 24.0 ;
    } else {
        let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
        if clean { score -= 16.0 ; }
