            let chain_bonus = if chain_post == 0 { 26.0 } else if chain_post <= 4 { 17.0 } else if chain_post <= 10 { 7.0 } else { 0.0 } ;
            score -= 30.0 * (1.0 - snug / cap) + chain_bonus ;
        } else {
            let gap = (next_item_size - post) as f64 ;
            score += 8.0 + gap * (if gap > 28.0 { 0.16 } else { 0.55 }) ;
            score += (nx - post as f64) * (0.5 + 0.5 * progress) ;
        }
    }
    let pr = post_residual as f64 ;
    let base = pr * pr / cap ;
    score += base * (0.5 + 0.5 * progress * progress) ;
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 2.0 * tightness * pr / cap ;
    if fitting_bins_count <= 1 {
        score -= 10.0 + 5.0 * progress ;
    }
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64) . recip () } ;
        score += 14.0 * scarcity + 6.0 * (1.0 - progress) ;
        if next_item_size > 0 && bin_residual >= item_size {
            let dead = (bin_capacity - item_size) as f64 ;
            if dead > 45.0 { score -= 10.0 ; }
        }
        let item = item_size as f64 ;
        if item > 0.55 * cap && fitting_bins_count <= 1 {
            score -= 20.0 * (item / cap - 0.55) ;
        }
    } else {
        if post > 0 && next_item_size > 0 && post < next_item_size {
            score += 2.0 ;
            score += 0.04 * post as f64 * (1.0 + progress) ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64) . min (6.0) ;
        }
        let dev = (bin_residual as f64 - mean_residual) . abs () ;
        score += 0.05 * dev ;
        if fitting_bins_count <= 2 && post <= 2 {
            score -= 9.0 ;
        }
    }
    score -= 3.0 * tightness * pr / cap ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: non-linear polynomial in post_residual (favor tight fits).
    let x = post / cap; // normalized post residual in [0,1)
    let mut score = 40.0 * x * x + 10.0 * x;

    // Smooth progress coupling: later in the stream, tighten more aggressively.
    score *= 1.0 + 1.5 * progress * (1.0 - progress + 0.25);
    score += 30.0 * progress * x * x;

    // Penalize residual far from mean residual (dead-space dispersion), smoothly.
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead: reward residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let fit_quality = 1.0 - ((post - nx) / cap);
            score -= 8.0 * fit_quality * (1.0 - progress);
        } else {
            // residual too small for next item: smooth penalty proportional to shortfall
            score += 6.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strong smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x) * (1.0 + 0.5 * progress);
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.4 * open_bins_count as f64 * x;

    // Brand-new empty bin candidate: penalize unless current residual is unusable waste.
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 && next_item_size <= item_size { 0.0 } else { 1.0 };
        score += 25.0 - 15.0 * waste * progress;
        if fitting_bins_count <= 1 {
            score -= 10.0; // no good alternative exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with sharpened emphasis on small post residuals.
    if post_residual <= 5 {
        score -= 30.0; // near-perfect fit
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: dead-space buckets.
    // Residuals in (0,10] are "prime" reusable zones for small items;
    // residuals in (10,30] are moderately useful; >30 is loose space.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -40.0,                 // exact fill: ideal
        1..=5 => -20.0,
        6..=10 => -8.0,
        11..=20 => 4.0,
        21..=30 => 8.0,
        _ => 12.0,
    };
    score += class;

    // Modulo arithmetic: residual divisible by common item sizes is more reusable.
    if pr > 0 {
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 6.0;
            }
        }
        // Residual that is itself a plausible item size (10..80) is highly reusable.
        if pr >= 10 && pr <= 80 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nxt_post = pr - next_item_size;
            if nxt_post <= 10 {
                score -= 12.0;
            } else {
                score -= (nxt_post as f64) * 0.15;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size as f64 - pr as f64).min(20.0) * 0.4;
        }
    } else {
        // Last item: prefer tightest fit, no future to consider.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin starts with residual == capacity.
    if bin_residual == bin_capacity {
        // Early stream: opening bins is fine (spreads load). Late stream: prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 25.0 * progress;
        // Large items relative to capacity benefit from fresh bins early.
        if (item_size as f64) > 0.6 * bin_capacity as f64 && progress < 0.5 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: if open bins are already loose on average,
    // mildly penalize this bin if it's much looser than the mean.
    let diff = (bin_residual as f64) - mean_residual;
    if diff > 0.0 {
        score += diff * 0.05;
    } else {
        score += diff * 0.02; // slightly reward tighter-than-average bins
    }

    // Prefer bins with larger current residual when many bins are open
    // (consolidation pressure), scaled by open bin count.
    score -= (open_bins_count.min(20) as f64) * 0.15 * (bin_residual as f64 / bin_capacity as f64);

    score
}

