    } else if post <= 3 {
        score -= 42.0 ;
    } else if post <= 6 {
        score -= 22.0 ;
    } else {
        let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
        if clean {
            score -= 16.0 ;
        } else if post % 5 == 0 {
            score -= 6.0 ;
        } else if post < 12 {
            score += 36.0 ;
        } else if post < 20 {
            score += 12.0 ;
        }
        if post >= 10 && post % 25 <= 10 {
            score -= 5.0 ;
        }
