    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.5 * progress * norm_post);

    // Quadratic interaction: penalize moderate dead space more as stream progresses
    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress * norm_item;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (nxt / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Slight penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln1p() * (post - mean_residual).abs();

    // New-bin candidate: neutral baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are preferred.
    let cap_frac = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward post_residuals that are exactly divisible by common sizes (harmonic fit)
    if post_residual > 0 {
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                harmonic_bonus += 3.0;
            }
        }
        score -= harmonic_bonus;
    } else {
        // Perfect fit: strongly favored
        score -= 25.0;
    }

    // Penalize small dead space: leftovers that no item (min size 1..10) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    if post <= cap_frac * 0.2 {
        score += 8.0; // near-full bin: tight fit, slight penalty unless perfect
    }
    if post >= cap_frac * 0.5 {
        score -= 4.0; // keeps a half-capacity-class residual: very reusable
    }

    // Integer-division class of next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how "harmonically" it fits
            let classes = post_residual / next_item_size.max(1);
            score -= 2.0 * classes as f64;
        } else {
            score += 5.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Early stream: consolidate into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > post {
        score += 3.0 * (mean_residual - post) / cap_frac;
    }
    if progress < 0.3 {
        score -= 2.0; // prefer filling existing bins early
    }

    // New-bin candidate: penalize opening a bin unless current residual is very poor
    if bin_residual == bin_capacity {
        if post_residual == bin_capacity && item_size <= bin_capacity {
            // item fits an empty bin; only prefer new bin if no tight fits exist
            score += 12.0;
        }
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (<= 10)
    // or too small to hold the lookahead item while remaining useful.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // If the lookahead item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post residual cannot hold the next item but is moderately large:
    // wasted space relative to lookahead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last chance: if this is the only bin that can fit the item, favor it strongly
    // to avoid opening a new bin for a poorly-fitting item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are already open; discourage unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bin count pressure.
        score += 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        // If item is large relative to typical residuals, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Open-bin pressure: mildly prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to mean (keep residuals balanced),
    // slightly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Late in the stream, tighten packing: penalize large post residuals more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Partial lookahead reward: next item fits in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }
