    // Favor bins with residual below mean residual (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for opening new bins early in the stream is discouraged;
    // penalize new-bin candidate mildly so existing bins are preferred when reasonable.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Small penalty for very large leftover waste relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny dead space is fine (unusable anyway, but low waste)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
