    // new-bin candidate: open only when scarcity / large item justifies it
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        score = pr + 8.0 + 6.0 * progress - 2.0 * tightness;
