        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64;
            score += 0.12 * tight / cap * (fitting_bins_count as f64).min(6.0);
        }
        // small unusable residual penalty when lookahead can't use it
        if next_item_size > 0 && post > 0 && post < next_item_size {
            score += 2.0 + 0.04 * post as f64 * (1.0 + progress);
        }
        if fitting_bins_count <= 2 && post <= 2 {
            score -= 9.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
