    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good fit exists or stream is early
    // and current bins are fragmented.
    if bin_residual == bin_capacity {
