        }
    }

    // Mild penalty if this bin is far from the mean residual (fragmentation).
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: neutral baseline with slight progress-dependent reluctance.
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.4 * progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo common item sizes
    let pr = post_residual;
    // Residuals that are "harmonically useful" (multiples / sums of small sizes) are less penalized
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr <= 10 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: waste tiering
    let tier = pr / 20; // 0..=4
    score += tier as f64 * 6.0;

    // Lookahead coupling: does next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportionally to how well next item harmonizes with post residual
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack.min(12.0) * 0.4;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 8.0; // exact harmonic chain
            }
        } else {
            score += 5.0; // next item won't reuse this bin
        }
    } else {
        // last item: prefer filling tightly
        score -= 20.0;
    }

    // Capacity fraction of current fill
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 10.0; // prefer fuller bins

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a bin unless existing residuals are hopeless
    if bin_residual == bin_capacity {
        let base = 55.0;
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / cap) * 20.0
        } else {
            0.0
        };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score = base + pressure + scarcity;
        // late in stream, slightly discourage proliferation
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild penalty if this bin's residual is far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest
    // plausible item (min item size assumed ~1..10 band) or if it is small
    // relative to the capacity. Penalize tiny-but-nonzero gaps quadratically.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver: strong penalty
        score += (10.0 - pr) * 6.0;
    }

    // Reward tight fits: the smaller the post_residual (while usable), the better.
    // Use a convex reward so near-perfect fits dominate.
    score -= (bin_capacity as f64 - pr).ln().max(0.0) * 4.0;

    // Penalize leaving a gap that barely misses fitting the next item
    // (lookahead coupling): if next item would not fit, this creates dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && pr >= (nxt * 0.5) {
            score += (nxt - pr) * 2.5; // near-miss gap: wasteful
        } else if pr >= nxt {
            score -= 3.0; // next item still fits here: good chaining
        }
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but strongly discourage opening new bins when alternatives exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to how many bins are open
        // and how many bins could already fit the item.
        score += 18.0 + 4.0 * open_bins_count as f64 + 10.0 * fitting_bins_count as f64;
        // Exception: if the item is huge relative to mean residual, opening
        // a fresh bin may be justified — relax the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 && mean_residual < item_size as f64 * 0.9 {
            score -= 30.0;
        }
    } else {
        // Existing bin: mild reward when this is the last fitting bin
        // (avoid opening a new bin unnecessarily).
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Slight preference for bins with lower residual (best-fit bias)
        // already captured by base post_residual term; add coupling with
        // mean residual: prefer filling below-average-residual bins.
        if pr < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Late-stream pressure: as the stream ends, avoid opening bins and
    // prefer consolidating into tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
