    // Relative to mean residual: bins below-average residual are tighter, prefer filling them.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it's genuinely better than a poor fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless the item is large relative to capacity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 70.0 - 20.0 * (item_size as f64 / bin_capacity as f64) - 10.0 * progress;
        // If next item is huge, a fresh bin is more flexible.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

