pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty on large dead space (wasted capacity), superlinear.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64;
            score -= 25.0 * snug;
        } else {
            // next item cannot fit here; penalize leaving tight residuals that block it
            score += 8.0 * (nx / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it strongly.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer bins with fewer alternatives (preserve flexibility elsewhere)
        score += 2.0 * (fitting_bins_count as f64).min(6.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // small residual is nearly a perfect fit
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0 + 10.0 * progress;
    }

    // Early in the stream, keep bins balanced (avoid fragmenting); late, pack greedily.
    if progress < 0.3 {
        score += 5.0 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    } else {
        score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Discourage opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count >= 1 && post_residual <= 20 {
            score += 40.0; // don't open new bin when a near-perfect open-bin fit exists
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post as f64 * 0.95 + ((bin_capacity / 10) as f64) * 0.05 ;
    if post == 0 {
        score -= 82.0 ;
    } else if post <= 3 {
        score -= 42.0 ;
    } else if post <= 6 {
        score -= 24.0 ;
    } else {
        let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
        if clean {
            score -= 16.0 ;
        } else if post < 12 {
            score += 36.0 ;
        } else if post < 20 {
            score += 12.0 ;
        }
    }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post >= next_item_size {
            let snug = (post - next_item_size) as f64 ;
            let chain_post = post - next_item_size ;
            let chain_bonus = if chain_post == 0 { 26.0 } else if chain_post <= 4 { 17.0 } else if chain_post <= 10 { 7.0 } else { 0.0 } ;
            score -= 30.0 * (1.0 - snug / cap) + chain_bonus ;
        } else {
            let gap = (next_item_size - post) as f64 ;
            score += 8.0 + gap * (if gap > 28.0 { 0.16 } else { 0.55 }) ;
            score += (nx - post as f64) * (0.35 + 0.4 * progress) ;
        }
    }
    let pr = post_residual as f64 ;
    let base = pr * pr / cap ;
    score += base * (0.5 + 0.5 * progress * progress) ;
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 2.0 * tightness * pr / cap ;
    if fitting_bins_count <= 1 {
        score -= 10.0 + 5.0 * progress ;
    }
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64) . recip () } ;
        score += 14.0 * scarcity + 6.0 * (1.0 - progress) ;
        if next_item_size > 0 && bin_residual >= item_size {
            let dead = (bin_capacity - item_size) as f64 ;
            if dead > 45.0 {
                score -= 10.0 ;
            }
        }
        let item = item_size as f64 ;
        if item > 0.55 * cap && fitting_bins_count <= 1 {
            score -= 20.0 * (item / cap - 0.55) ;
        }
    } else {
        if post > 0 && next_item_size > 0 && post < next_item_size {
            score += 2.0 ;
            score += 0.04 * post as f64 * (1.0 + progress) ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64) . min (6.0) ;
        }
        let dev = (bin_residual as f64 - mean_residual) . abs () ;
        score += 0.05 * dev ;
        if fitting_bins_count <= 2 && post <= 2 {
            score -= 9.0 ;
        }
    }
    score -= 3.0 * tightness * pr as f64 / cap ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = r * (1.0 + 0.6 * progress) - 0.35 * r * r / cap * (1.0 - progress);

    // Reward tight fits: post_residual small relative to capacity
    score -= (1.0 - rn) * (1.0 - rn) * 8.0;

    // Last-chance bin: strong bonus, modulated smoothly by progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins whose residual diverges from mean residual (dead space control)
    score += ((r - mean_residual).abs() / cap) * 5.0;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as f64) <= r {
            score -= 6.0 * (1.0 - r / cap.max(1.0)) + 2.0;
        } else {
            // post residual too small for next item: mild penalty scaled by waste
            score += 3.0 * (r / cap);
        }
    }

    // Slight preference for fewer open bins early, more consolidation late
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate: neutral-ish baseline with smooth progress-based cost
    if bin_residual == bin_capacity {
        score += cap * (0.9 + 0.4 * progress);
    }

    score
}

