pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space quality classes ---
    // Class residual into bands via integer division on capacity fractions.
    // post_residual / (capacity/8) gives 8 harmonic octaves of leftover space.
    let octave = (post_residual * 8) / bin_capacity; // 0..=7
    let octave = octave.min(7);

    // Small leftovers (octave 0,1) are near-useless dead space: penalize hard.
    score += match octave {
        0 => 40.0,
        1 => 25.0,
        2 => 8.0,
        3 => 0.0,
        4 => -6.0,
        5 => -10.0,
        6 => -12.0,
        _ => -14.0,
    };

    // Perfect-fit harmonic: post_residual exactly divisible by small item classes
    // (items 1..100, so divisible by 10 or 25 classes are reusable).
    if post_residual == 0 {
        score -= 100.0; // exact fit is ideal
    } else if post_residual % 10 == 0 {
        score -= 15.0;  // residue aligned to decile class
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual < 10 {
        score += 30.0;  // sub-minimal dead space
    }

    // --- Lookahead coupling: does next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by tightness.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 + 25.0 * tight;
        } else {
            // Next item cannot use leftover: penalize proportionally to waste.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 20.0 * waste;
            // If next item is large, leftover is even less likely to be used later.
            if next_item_size > bin_capacity / 2 {
                score += 8.0 * waste;
            }
        }
    }

    // --- Last-chance pressure: only one fitting bin, avoid forcing a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when
        // existing bins are fragmented (high mean residual spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        // Base penalty so we prefer filling open bins; relax late in stream.
        score += 55.0 - 20.0 * progress;
        // If item is huge (leaves little room), a fresh bin is fine.
        if item_size >= (bin_capacity * 7) / 10 {
            score -= 35.0;
        }
        // If open bins are on average nearly full, new bin is natural.
        if mean_residual < bin_capacity as f64 * 0.2 {
            score -= 25.0;
        }
        // Penalize new bin if it would be only marginally better than reuse.
        if fragmentation < 5.0 {
            score += 10.0;
        }
        let _ = open_bins_count;
    }

    // --- Mild tie-break: prefer bins with residual close to item (tight fit) ---
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * tightness;

    // --- Stream-phase modulation: early on, keep bins flexible; late, pack tight ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
