    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of next_item_size into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let gap = (post_residual as f64 - next) / bin_capacity as f64;
            // Perfect chain (post_residual == next_item_size) is excellent.
            score -= 25.0 * (1.0 - gap);
            if post_residual == next_item_size {
