        score -= 10.0;
    }

    // Relative to mean residual: prefer bins that keep residual distribution balanced,
    // but allow concentrated small residuals (good packing).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64 * tightness;

    score
}

