        score -= 42.0 ;
    } else if post <= 6 {
        score -= 24.0 ;
    } else {
        let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
        if clean { score -= 16.0 ; }
        else if post < tenth { score += 30.0 ; }
        else if post < fifth { score += 12.0 ; }
        else if post < quarter { score += 4.0 ; }
        if post >= 10 && post % 25 <= 10 { score -= 5.0 ; }
    }

    if next_item_size > 0 {
        let nx = next_item_size ;
        if post == nx {
