        }
    }

    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr < nx { score += (nx - pr) * (0.5 + 0.5 * progress) ; }
        else { score -= 0.5 * (pr - nx) . min (20.0) / cap ; }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 40.0 ; }

    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64) . recip () } ;
        score += 30.0 * scarcity + 20.0 * (1.0 - progress) ;
        if mean_residual < cap * 0.25 { score -= 15.0 ; }
        if next_item_size > 0 && bin_residual >= item_size {
            let dead = (bin_capacity - item_size) as f64 ;
            if dead > 45.0 { score -= 10.0 ; }
        }
        let item = item_size as f64 ;
        if item > 0.55 * cap && fitting_bins_count <= 1 { score -= 20.0 * (item / cap - 0.55) ; }
