    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight-fit reward: smooth polynomial coupling of fill ratio with progress
    let fill = (bin_residual as f64 - post) / cap;
    let tightness = fill * fill * (1.0 - fill);
    score -= 40.0 * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (waste amplification)
    let waste = post - mean_residual;
    score += 0.15 * waste * waste / cap;

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let nxt = next_item_size as f64;
        let reuse = 1.0 - ((post - nxt) / cap).abs();
        score -= 8.0 * reuse * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - post / cap);
    }

    // Early stream: mildly prefer consolidating into fewer bins
    score += 3.0 * (open_bins_count as f64) * (1.0 - progress) * (post / cap);

    // New-bin candidate: penalize slightly unless current fit is bad
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10-unit classes
    let class = (post_residual / 10) as f64;
    score += 6.0 * class;

    // Penalize leftovers that are awkward (not divisible into small usable chunks)
    let rem = post_residual % 10;
    if rem > 0 {
        score += 4.0 - rem as f64 * 0.4;
    }

    // Reward tight fits: post_residual small relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * tightness;

    // Harmonic compatibility with lookahead item (modulo classes of next_item_size)
    if next_item_size > 0 && post_residual >= next_item_size {
        let compat = (post_residual % next_item_size.max(1)) as f64;
        score -= 8.0 - compat * 0.5;
        score -= 10.0;
    } else if next_item_size > 0 {
        // next item cannot follow into this bin -> dead space penalty scaled by next size class
        let nxt_class = (next_item_size / 10) as f64;
        score += 3.0 * nxt_class;
    }

    // Last-chance bin: strongly favor using it before opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current fit is very poor
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 12.0;
        if post_residual > 0 && post_residual <= 15 {
            score -= 25.0; // tight fit into fresh bin is fine
        }
        if waste < mean_residual {
            score += 5.0;
        }
        // early stream: prefer opening bins to build diversity
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            score -= 6.0;
        }
    }

    // Prefer bins with residual close to mean (balanced packing)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Many open bins: discourage spreading
    if open_bins_count > 8 {
        score += 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear "gap trap").
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item would fit in the post residual, reward leaving that space.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 4.0;
    }

    // Early in stream: be slightly more willing to open bins for good fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Mild tie-break toward bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit: penalize proportional to dead space created
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize leaving residual far below the mean (fragmenting space)
    let residual = post_residual as f64;
    if residual < mean_residual {
        score += 0.3 * (mean_residual - residual);
    } else {
        score -= 0.1 * (residual - mean_residual);
    }

    // Progress: late in stream, prefer tighter packing (smaller post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * residual * 0.2;

    // New-bin candidate: make it unattractive unless residual is large/empty
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: scale dead space quadratically.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize leaving a gap the next item almost fits (wasted potential).
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += 0.3 * gap;
        }
        // If this bin could hold both current and next item, big reward.
        if bin_residual >= item_size + next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are penalized early/mid stream, slightly less late.
        score += 45.0 - 20.0 * progress;
        // Attractive if existing bins have large mean residual? No: large mean residual
        // means open bins have room, so penalize new bin more.
        score += 0.4 * mean_residual;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Prefer filling bins that are already relatively full (small residual before placement).
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth quartic coupling of wasted space with stream progress:
    // later in the stream, dead space becomes more costly
    let waste_penalty = pr_norm.powi(2) * (1.0 + 3.0 * progress) * 40.0;
    score += waste_penalty;

    // Cubic interaction: normalized residual vs mean residual divergence
    let mean_norm = mean_residual / cap;
    let divergence = pr_norm - mean_norm;
    score += divergence.powi(3) * 25.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward strongly
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_bonus = (-gap / 20.0).exp() * 15.0;
        score -= fit_bonus;
    } else {
        // last item: minimize waste aggressively
        score += pr_norm * 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins mildly, more so early when bins are few
        score += 10.0 + 5.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        // but if it's the last item, an empty bin is fine
        if next_item_size == 0 {
            score -= 25.0;
        }
    }

    // Smooth sigmoid pressure against hoarding many nearly-empty bins
    let hoard = 1.0 / (1.0 + (-6.0 * (pr_norm - 0.5)).exp());
    score += hoard * 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
