    // this placement is excellent; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: reward a tight combined packing.
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item would not fit here: slight penalty for stranding.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += gap * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well. Compare against mean residual.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: penalize by mean residual of open bins
        // (wasting existing capacity) and by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + mean_residual * 0.25 + progress * 10.0;
        // But if many open bins exist and mean residual is tiny (fragmented),
        // opening fresh is less bad: reduce penalty.
        if open_bins_count > 3 && mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Integer-division threshold: bins whose residual after placement is in
    // the "half-full" band (post_residual ~ half of capacity) are flexible.
    if post_residual >= 40 && post_residual <= 55 {
        score -= 4.0;
    }

    // Slight preference for tighter bins when many bins are open (consolidation).
    score += (open_bins_count as f64) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins when alternatives exist.
    if open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64 - 3.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when it enables a good future pairing
    // (e.g., item + next item sum near capacity) or the item is large.
    if bin_residual == bin_capacity {
        let pairing = (item_size + next_item_size) as f64;
        if next_item_size > 0 && pairing >= bin_capacity as f64 * 0.9 {
            score -= 30.0; // opening fresh bin pairs well with next item
        } else if item_size >= 60 {
            score -= 10.0;
        } else if fitting_bins_count > 0 {
            score += 45.0; // discourage abandoning usable open bins for small items
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight bonus for using this bin now.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 - slack * 3.0;
    }
    // Next item does NOT fit in the leftover: dead space penalty
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 60.0;
    }

    // Penalize small unusable residuals (dead space below min item size)
    if post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) > mean_residual;
        if decent_fit_exists || (fitting_bins_count == 1 && post_residual >= 10) {
            score += 200.0;
        } else {
            score += 20.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream -> be more frugal, avoid opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual is the base; scale it by item density.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 0.35 * fill_ratio * (bin_capacity as f64 - post_residual as f64);

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // awkward zone
    }

    // Lookahead: if the next item fits exactly-ish into post_residual, strong bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize hoarding space.
            score += 4.0;
        }
    }

    // Last chance: only one bin can fit this item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) modulated by global state.
    let diff = (bin_residual as f64 - item_size as f64);
    score += 0.10 * diff;

    // Global state coupling: many open bins with high mean residual -> prefer reusing
    // bins with large residuals rather than fragmenting.
    if open_bins_count > 0 {
        let mr = mean_residual;
        if bin_residual as f64 > mr {
            score -= 0.05 * (bin_residual as f64 - mr);
        } else {
            score += 0.08 * (mr - bin_residual as f64);
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Early stream: opening bins is cheap; late stream: expensive.
        let base = 0.5 * bin_capacity as f64;
        let time_penalty = progress * 0.6 * bin_capacity as f64;
        let crowd_penalty = 0.15 * open_bins_count as f64;
        // If no open bin fits (fitting_bins_count == 0 among open bins), new bin is fine.
        let relief = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score = base + time_penalty + crowd_penalty - relief;
        // If item is large, opening a fresh bin is often good.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large post-residuals super-linearly (dead space avoidance)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual gets a discount
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin bonus: avoid opening new bins when few fit
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Slight penalty for spreading across many bins vs mean residual alignment
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // Late-stream consolidation: favor filling existing bins more strongly
    score -= 10.0 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly host a future item. Items are 1..=100; small residuals (<10)
    // are near-useless, mid residuals are valuable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 40.0; // dead space penalty
    } else if pr < 20 {
        score += 15.0;
    }

    // Modulo classes: residuals congruent to small values mod common item
    // sizes are more likely to be filled exactly later.
    let harmonic_bonus = ((pr % 10) as f64) * 0.5 + ((pr % 25) as f64) * 0.3;
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item cannot fit here; penalize proportionally to waste
            score += ((next_item_size - pr) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when current bin is tight/awkward
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base bias so new bins are slightly worse than decent fits,
        // but better than bins with tiny residuals.
        score = 60.0 + (mean_residual / cap) * 20.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 30.0; // big next item: fresh capacity valuable
        }
        if open_bins_count > 8 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 && bin_residual < bin_capacity {
            score += 100.0; // never steal a last-chance placement
        }
    }

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= progress * 25.0;
    }

    // Tightness coupling: prefer bins where item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
