pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance with open-bin pressure.
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything
    // (below the minimum plausible item size) are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Penalize small-but-unusable gaps harder than large gaps:
    // a residual of 0 is perfect; residuals in (0, ~20) are dead weight.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 3.0;
    }

    // Reward tight fits: bonus proportional to how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage scattering items across many bins
    // unless the fit is good; new empty bins get an opening penalty.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less when nothing fits well.
        score += 40.0 + open_bins_count as f64 * 2.0;
        // If lookahead item is large, opening a fresh bin may pay off.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        score -= 5.0; // mild reward for using an existing bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Align with global mean residual: prefer bins whose post-residual
    // stays near the mean (keeps future items placeable).
    score += 0.3 * (pr - mean_residual).abs();

    // Early in the stream, be slightly more willing to open bins;
    // late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: small leftover is good
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            // next item doesn't fit: penalize wasted residual relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Compare post residual to mean residual: keeping residuals balanced is good
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only bin that fits, prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when an open bin fits reasonably
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 30.0; // new bin fine if nothing else could hold future item anyway
        }
    }

    // Penalize large dead space relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - post / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += 30.0 * (10.0 - post);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 18.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Global state: prefer filling bins when many are open with low mean residual
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread = post - mean_residual;
    score += 0.15 * spread;
    score -= 8.0 * (open_bins_count as f64 / (1.0 + progress * 5.0)) * (mean_residual / cap);

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = if fitting_bins_count > 0 {
            let waste = (bin_residual - item_size.min(bin_residual)) as f64;
            (waste / cap).clamp(0.0, 1.0)
        } else { 0.0 };
        score = cap * 0.9 + 40.0 * desperation * (1.0 - progress) - 55.0 * poor_fits + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate slack (weight down); late, tighten (weight up)
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Smooth penalty for mid-range dead space (x ~ 0.4-0.6 is worst: too big for small items, too small for large)
    let mid = 4.0 * x * (1.0 - x); // peaks at x=0.5
    score += 8.0 * mid * mid * (1.0 + progress);

    // Reward very tight fits (x near 0) with a smooth bonus
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - 4.0 * slack * (1.0 - slack)) * (0.5 + progress);
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for bins below mean residual early (balance load), above late (consolidate)
    score += (mean_residual - pr) * (0.3 - 0.6 * progress);

    // Mild penalty for proliferating bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless post residual would be near-perfect for future use
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * progress * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Classify residual into harmonic bands: (0..=5], (5..=10], (10..=25], (25..=50], (50..)
    let band = if post_residual == 0 { 0.0 }
        else if post_residual <= 5 { 1.0 }
        else if post_residual <= 10 { 2.0 }
        else if post_residual <= 25 { 3.0 }
        else if post_residual <= 50 { 4.0 }
        else { 5.0 };

    // Small residuals are dead space -> penalize band 1/2 slightly, reward larger usable space
    score += band * 3.0;

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Residuals in 1..10 are hard to fill with items >=1 but small items exist; mild penalty
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // exact match of next item to post residual is a jackpot
        if next_item_size == post_residual {
            score -= 40.0;
        } else {
            // reward proportionally to how much of the residual next item consumes
            let usage = next_item_size as f64 / post_f;
            score -= 10.0 * usage;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; residual risks becoming dead space
        let waste = post_f;
        score += 0.05 * waste;
        // if residual is large but next item doesn't fit, mild penalty
        if post_residual > 40 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive if current item is small (saves big bins)
        // or if no good fit exists among open bins
        score = 60.0;
        if next_item_size > 0 {
            // if next item is large, a fresh bin preserves capacity for it
            score -= (next_item_size as f64) * 0.2;
        }
        // late in the stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
