pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let remaining = total_items . saturating_sub (step_index) ;
    let mut score = post as f64 ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if post_residual < 10 {
            score += 40.0 ;
        } else if post_residual < 20 {
            score += 25.0 ;
        } else if post_residual < 40 {
            score += (40.0 - post_residual as f64) * 0.6 ;
        } else {
            score -= 5.0 ;
        }

        if post <= 3 {
            score -= 45.0 ;
        } else if post <= 6 {
            score -= 26.0 ;
        } else {
            let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
            if clean {
                score -= 18.0 ;
            } else if post < 12 {
                score += 36.0 ;
            } else if post < 20 {
                score += 12.0 ;
            }
        }

        if post > 0 && post < 15 {
            let awkward = (post % 3 != 0) && (post % 7 != 0) && (post % 5 != 0) ;
            if awkward { score += 9.0 ; }
        }
    }

    // residual usefulness coupling
    if post > 0 {
        let nx = next_item_size as f64 ;
        let usable_scale = if nx > 0.0 { nx.max(mean_residual.max(1.0)) } else { mean_residual.max(1.0) } ;
        if (post as f64) < usable_scale * 0.35 {
            score += 14.0 * (1.0 - post as f64 / (usable_scale * 0.35)) ;
        }
        if next_item_size > 0 && post > next_item_size && (post - next_item_size) as f64 <= 4.0 {
            score -= 10.0 ;
        }
        // dead-space: leftover that no plausible future item can use
        if next_item_size > 0 && post < next_item_size && (post as f64) < mean_residual * 0.8 {
            score += 4.0 * (1.0 - post as f64 / (mean_residual * 0.8).max(1.0)) ;
        }
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post >= next_item_size {
            let snug = (post - next_item_size) as f64 ;
            let chain_post = post - next_item_size ;
            let chain_bonus = if chain_post == 0 { 34.0 } else if chain_post <= 4 { 20.0 } else if chain_post <= 10 { 8.0 } else { 0.0 } ;
            score -= 30.0 * (1.0 - snug / cap) + chain_bonus ;
            if chain_post == 0 { score -= 8.0 ; }
            if chain_post >= 1 && chain_post <= 12 && (chain_post as f64) <= mean_residual {
                score -= 6.0 ;
            }
            // two-step chain lookahead: after placing next item, residue fits it again
            if chain_post >= 1 && chain_post >= next_item_size && (chain_post - next_item_size) <= 2 {
                score -= 4.0 ;
            }
        } else {
            let gap = (next_item_size - post) as f64 ;
            score += 8.0 + gap * (if gap > 28.0 { 0.16 } else { 0.55 }) ;
        }
        if post > 0 && post < next_item_size && (post as f64 - mean_residual).abs() < 2.0 {
            score -= 4.0 ;
        }
        if post == next_item_size { score -= 6.0 ; }
        let _ = nx ;
    }

    let pr = post_residual as f64 ;
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 2.0 * tightness * pr / cap ;

    let fill_ratio = item_size as f64 / bin_residual . max (1) as f64 ;
    if fill_ratio > 0.6 && post_residual > 0 {
        score -= 5.0 * (fill_ratio - 0.6) * pr / cap * 10.0 ;
    }

    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0 ;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 ;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0 ;
    }

    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 30.0 ;
        score -= 20.0 * (1.0 - progress) ;
        if mean_residual < cap * 0.25 {
            score -= 17.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0 ;
        }
        if progress > 0.85 { score += 8.0 ; }
        let fill = item_size as f64 / cap ;
        score += 14.0 * fill ;
        if open_bins_count > 4 && mean_residual > cap * 0.12 {
            score += 6.0 ;
        }
        if fill > 0.55 && fitting_bins_count <= 1 {
            score -= 20.0 * (fill - 0.55) ;
        }
        // allow new bin when open residuals are large but fragmented relative to stream
        if fitting_bins_count > 0 && mean_residual > cap * 0.35 && fill > 0.4 {
            score -= 10.0 ;
        }
        if remaining < 6 { score += 18.0 ; }
    } else {
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > mean_residual * 1.5 && post_residual < next_item_size {
            score += 6.0 ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64).min(6.0) ;
        }
        // when few bins fit, strongly reward tight fills
        if fitting_bins_count <= 2 {
            let tight = (bin_residual - item_size) as f64 ;
            if tight <= 4 { score -= (5.0 - tight as f64) * 2.0 ; }
        }
        if remaining < 6 && post_residual == 0 { score -= 12.0 ; }
    }

    if open_bins_count > 6 && post > 0 && post < 25 {
        score += 3.0 ;
    }

    score
}

