pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // possible item (1..100 interface => treat < 10 as near-dead) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    // Partial dead space: penalize residuals below 20 (hard to fill later) super-linearly.
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here; leftover becomes dead space risk.
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones;
    // when few are open, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a fillable direction.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate: make it moderately attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.0 && (item_size as f64) < 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // next item fits after this placement: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: penalize leaving moderately sized gap
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 {
                score += 30.0;
            }
        }
    } else {
        // last item: prefer perfect fit already handled; otherwise mild
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // new bin attractive only if item is big or current bins are fragmented
        score += 120.0 * (1.0 - fill_ratio);
        if mean_residual > item_size as f64 * 1.5 {
            score += 150.0; // open bins have room; discourage new bin
        }
        if open_bins_count == 0 {
            score -= 2000.0;
        }
    }

    // Early stream: keep bins open longer (consolidation), late: pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    // Penalize small unusable dead space (0 < post_residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    score
}

