    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0 ;
    }

    if bin_residual == bin_capacity {
        score += 30.0 ;
        score -= 20.0 * (1.0 - progress) ;
        if mean_residual < cap * 0.25 {
            score -= 17.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0 ;
        }
        if progress > 0.85 { score += 8.0 ; }
        let fill = item_size as f64 / cap ;
        score += 14.0 * fill ;
        if open_bins_count > 4 && mean_residual > cap * 0.12 {
            score += 6.0 ;
        }
        if fill > 0.55 && fitting_bins_count <= 1 {
            score -= 20.0 * (fill - 0.55) ;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.35 && fill > 0.4 {
            score -= 10.0 ;
        }
        let remaining = total_items . saturating_sub (step_index) ;
        if remaining < 6 { score += 18.0 ; }
        if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 && fitting_bins_count > 0 {
            score += 8.0 ;
        }
        // late stream: opening bins is cheap only if few remain; otherwise consolidate
        if remaining > 20 && open_bins_count > 3 {
            score += 4.0 ;
        }
        // NEW: gate new-bin opening — penalize when alternative placement leaves a large stranded gap
        if fitting_bins_count > 0 && next_item_size > 0 {
            let alt_post = (bin_residual - item_size) as f64 ;
            if alt_post > cap * 0.45 && alt_post < next_item_size as f64 {
                score -= 9.0 ;
            }
            if alt_post > cap * 0.6 && progress < 0.5 {
                score -= 4.0 ;
            }
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > mean_residual * 1.5 && post_residual < next_item_size {
            score += 6.0 ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64).min(6.0) ;
        }
        if fitting_bins_count <= 2 {
            let tight = (bin_residual - item_size) as f64 ;
            if tight <= 4 { score -= (5.0 - tight as f64) * 2.0 ; }
        }
        let remaining = total_items . saturating_sub (step_index) ;
        if remaining < 6 && post_residual == 0 { score -= 12.0 ; }
        if post_residual <= 2 {
            score -= 10.0 ;
        }
        // lookahead: reward bins whose post-residual can host the next two plausible items
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual > 0 {
            score -= 4.0 ;
        }
    }

    if open_bins_count > 6 && post > 0 && post < 25 {
        score += 3.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets reward "perfect" leftovers
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,                       // exact fill / round residual
        1 | 2 | 3 => score -= 4.0,                // nearly-round, still usable
        4 | 5 | 6 => score += 3.0,                // awkward middle dead space
        _ => score += 6.0,                        // 7..9 slivers
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 {
        score += 15.0;                            // dead-space penalty for tiny leftovers
    } else if pr <= quarter {
        score -= 6.0;
    } else if pr <= bin_capacity / 2 {
        score -= 2.0;
    }

    // Coupling with lookahead: does post_residual fit next item exactly or well?
    if next_item_size > 0 && next_item_size <= pr {
        let next_fit = pr - next_item_size;
        score -= (8.0 * (1.0 - next_fit as f64 / cap)).max(0.0);
        if next_fit % 10 == 0 {
            score -= 5.0;                         // harmonic chain: both residuals round
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 4.0;                             // next item won't chain here
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish, penalize when many open bins fit fine
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 8.0;
        if fitting_bins_count > 0 {
            score += 6.0 + 2.0 * fitting_bins_count.min(5) as f64;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;                         // big pair coming: fresh bin ok
        }
    }

    // Stream progression: tighten packing late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Spread-awareness: prefer bins near mean residual when residuals are tight
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for hoarding many open bins
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post as f64 ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if post_residual < 10 {
            score += 40.0 ;
        } else if post_residual < 20 {
            score += 25.0 ;
        } else if post_residual < 40 {
            score += (40.0 - post_residual as f64) * 0.6 ;
        } else {
            score -= 5.0 ;
        }

        if post <= 3 {
            score -= 45.0 ;
        } else if post <= 6 {
            score -= 26.0 ;
        } else {
            let clean = post % 20 == 0 || post % 25 == 0 || post % 10 == 0 ;
            if clean {
                score -= 18.0 ;
            } else if post < 12 {
                score += 36.0 ;
            } else if post < 20 {
                score += 12.0 ;
            }
        }

        if post > 0 && post < 15 {
            let awkward = (post % 3 != 0) && (post % 7 != 0) && (post % 5 != 0) ;
            if awkward { score += 9.0 ; }
        }

        // dead-space penalty: residual too small to hold the next plausible item
        if post > 0 {
            let nx = next_item_size as f64 ;
            let usable_scale = if nx > 0.0 { nx.max(mean_residual.max(1.0)) } else { mean_residual.max(1.0) } ;
            if (post as f64) < usable_scale * 0.35 {
                score += 14.0 * (1.0 - post as f64 / (usable_scale * 0.35)) ;
            }
            if next_item_size > 0 && post > next_item_size && (post - next_item_size) as f64 <= 4.0 {
                score -= 10.0 ;
            }
            if next_item_size > 0 && post < next_item_size && (post as f64) < mean_residual * 0.8 {
                score += 4.0 * (1.0 - post as f64 / (mean_residual * 0.8).max(1.0)) ;
            }
            if next_item_size > 0 && post > next_item_size * 2 {
                score += 0.10 * ((post - next_item_size * 2) as f64) ;
            }
            if next_item_size > 0 && post < next_item_size && (post as f64) < mean_residual * 0.4 {
                score += 6.0 ;
            }
            // dead-space ratio: fraction of bin wasted after this placement
            let dead_ratio = post as f64 / bin_residual . max (1) as f64 ;
            if dead_ratio > 0.5 {
                score += 8.0 * (dead_ratio - 0.5) ;
            }
            // stream-aware dead-space: stranded residual weighted by remaining stream length
            if post > 0 && next_item_size > 0 && post < next_item_size {
                let dead_frac = (next_item_size - post) as f64 / cap ;
                let urgency = (1.0 - progress * 0.5).max(0.5) ;
                score += 14.0 * dead_frac * urgency ;
            }
            if post > 0 && (post as f64) < mean_residual * 0.22 {
                score += 7.0 ;
            }
        }
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post >= next_item_size {
            let snug = (post - next_item_size) as f64 ;
            let chain_post = post - next_item_size ;
            let chain_bonus = if chain_post == 0 { 34.0 } else if chain_post <= 4 { 20.0 } else if chain_post <= 10 { 8.0 } else { 0.0 } ;
            score -= 30.0 * (1.0 - snug / cap) + chain_bonus ;
            if chain_post == 0 { score -= 8.0 ; }
            if chain_post >= 1 && chain_post <= 12 && (chain_post as f64) <= mean_residual {
                score -= 6.0 ;
            }
            if chain_post > 12 && (chain_post as f64) >= mean_residual {
                score -= 3.0 * ((chain_post as f64) / cap) ;
            }
            if chain_post > 0 && chain_post as f64 <= mean_residual * 0.6 {
                score -= 5.0 ;
            }
            if chain_post >= 1 && chain_post >= next_item_size && (chain_post - next_item_size) <= 2 {
                score -= 4.0 ;
            }
            if chain_post > 0 && (chain_post % 10 == 0 || chain_post % 5 == 0) {
                score -= 5.0 ;
            }
        } else {
            let gap = (next_item_size - post) as f64 ;
            score += 8.0 + gap * (if gap > 28.0 { 0.16 } else { 0.55 }) ;
        }
        if post > 0 && post < next_item_size && (post as f64 - mean_residual).abs() < 2.0 {
            score -= 4.0 ;
        }
        if post == next_item_size {
            score -= 6.0 ;
        }
        let _ = nx ;
    }

    let pr = post_residual as f64 ;
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 2.0 * tightness * pr / cap ;

    let fill_ratio = item_size as f64 / bin_residual . max (1) as f64 ;
    if fill_ratio > 0.6 && post_residual > 0 {
        score -= 5.0 * (fill_ratio - 0.6) * pr / cap * 10.0 ;
    }

    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0 ;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 ;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0 ;
    }

    if bin_residual == bin_capacity {
        score += 30.0 ;
        score -= 20.0 * (1.0 - progress) ;
        if mean_residual < cap * 0.25 {
            score -= 17.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0 ;
        }
        if progress > 0.85 { score += 8.0 ; }
        let fill = item_size as f64 / cap ;
        score += 14.0 * fill ;
        if open_bins_count > 4 && mean_residual > cap * 0.12 {
            score += 6.0 ;
        }
        if fill > 0.55 && fitting_bins_count <= 1 {
            score -= 20.0 * (fill - 0.55) ;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.35 && fill > 0.4 {
            score -= 10.0 ;
        }
        let remaining = total_items . saturating_sub (step_index) ;
        if remaining < 6 { score += 18.0 ; }
        if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 && fitting_bins_count > 0 {
            score += 8.0 ;
        }
        if remaining > 20 && open_bins_count > 3 {
            score += 4.0 ;
        }
        // refined new-bin gate: avoid opening when it would strand a large awkward gap
        if fitting_bins_count > 0 && next_item_size > 0 {
            let alt_post = (bin_residual - item_size) as f64 ;
            if alt_post > cap * 0.45 && alt_post < next_item_size as f64 {
                score -= 9.0 ;
            }
            if alt_post > cap * 0.6 && progress < 0.5 {
                score -= 4.0 ;
            }
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > mean_residual * 1.5 && post_residual < next_item_size {
            score += 6.0 ;
        }
        if fitting_bins_count > 2 {
            let tight = (bin_residual - item_size) as f64 ;
            score += 0.12 * tight / cap * (fitting_bins_count as f64).min(6.0) ;
        }
        if fitting_bins_count <= 2 {
            let tight = (bin_residual - item_size) as f64 ;
            if tight <= 4 { score -= (5.0 - tight as f64) * 2.0 ; }
        }
        let remaining = total_items . saturating_sub (step_index) ;
        if remaining < 6 && post_residual == 0 { score -= 12.0 ; }
        if post_residual <= 2 {
            score -= 10.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size * 2 && post_residual > 0 {
            score -= 4.0 ;
        }
    }

    if open_bins_count > 6 && post > 0 && post < 25 {
        score += 3.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps are worse than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = pure dead space
    } else if post_residual < 25 {
        score += 25.0; // awkward mid gap, hard to fill with items >= 10
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Reward tight fits (small post_residual relative to item size)
    score -= (item_size as f64 / (post_residual as f64 + item_size as f64 + 1.0)) * 30.0;

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage proliferation of bins
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0; // dead space confirmed by lookahead
    }

    // New-bin candidate: only attractive when it would absorb a big chunk cleanly
    if bin_residual == bin_capacity {
        let base = 55.0 - (item_size as f64 - 50.0).abs() * 0.4;
        score = score.max(base) + 10.0;
        // prefer new bin when existing bins are fragmented
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    // Progress: later in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
